const crypto = require('crypto');
const secret = $env.STRIPE_WEBHOOK_SECRET || 'PLACEHOLDER_STRIPE_WEBHOOK_SECRET';
const sigHeader = $input.first().json.headers['stripe-signature'] || '';
const rawBody = $input.first().json.body /* ASSUMES this is the raw string, per the rawBody option on the Stripe webhook node - not verified */;

const parts = Object.fromEntries(sigHeader.split(',').map((kv) => kv.split('=')));
const signedPayload = `${parts.t}.${rawBody}`;
const expected = crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');

let valid = false;
try {
  valid = crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(parts.v1 || '', 'hex'));
} catch (e) {
  valid = false; // length mismatch etc. - definitely not a valid signature
}

const event = valid ? JSON.parse(rawBody) : null;
const SUCCESS_TYPES = ['checkout.session.completed', 'payment_intent.succeeded'];
// 06's audit-gap list: 'failed/declined payment handling - retry/dunning, distinct CRM state' -
// new this pass, previously only success events were classified at all.
const FAILED_TYPES = ['payment_intent.payment_failed', 'checkout.session.expired'];
const RELEVANT_TYPES = [...SUCCESS_TYPES, ...FAILED_TYPES];

// Tier prices per portal/netlify/functions/lib/createCheckoutSession.ts's TIER_PRICES_CENTS -
// reverse-looked-up from the paid amount rather than trusting a metadata field, since the portal
// doesn't currently set a tier metadata key (only opportunityId) - avoids needing a second
// coordinated change over there for this workflow to know what was actually purchased.
const TIER_PRICES_CENTS = { Gold: 75000, Platinum: 165000, Iridium: 260000 };
const amountTotal = event?.data?.object?.amount_total ?? event?.data?.object?.amount ?? null;
const tier = Object.keys(TIER_PRICES_CENTS).find((t) => TIER_PRICES_CENTS[t] === amountTotal) || 'Unknown';

return [{
  json: {
    ok: valid,
    handled: valid && RELEVANT_TYPES.includes(event?.type),
    isFailure: valid && FAILED_TYPES.includes(event?.type),
    eventType: event?.type,
    opportunityId: event?.data?.object?.metadata?.opportunityId,
    amountTotalCents: amountTotal,
    tier,
    failureReason: event?.data?.object?.last_payment_error?.message || null,
  },
}];
